import type { AspectRatio, RenderSpec, Template, TemplateCategory } from "@/lib/types";
import { DEFAULT_SPEC, mergeSpec } from "@/lib/render/defaults";
import { slugify } from "@/lib/utils";

interface TemplateInput {
  name: string;
  category: TemplateCategory;
  tags?: string[];
  is_pro?: boolean;
  credits_per_min?: number;
  popular?: boolean;
  aspect_ratios?: AspectRatio[];
  description: string;
  spec: Partial<RenderSpec>;
}

const ALL_RATIOS: AspectRatio[] = ["9:16", "1:1", "16:9", "4:5"];

function make(input: TemplateInput): Template {
  return {
    id: slugify(input.name) || Math.random().toString(36).slice(2),
    name: input.name,
    category: input.category,
    tags: input.tags ?? [],
    is_pro: input.is_pro ?? false,
    credits_per_min: input.credits_per_min ?? 1,
    popular: input.popular ?? false,
    aspect_ratios: input.aspect_ratios ?? ALL_RATIOS,
    preview_video_url: null,
    thumbnail_url: null,
    description: input.description,
    spec: mergeSpec(DEFAULT_SPEC, input.spec),
    published: true,
    created_by: null,
  };
}

